    """Extract pointwise rating [[N]] where N in 1-10. Returns float or None."""
    match = re.search(r"\[\[(\d+(?:\.\d+)?)\]\]", raw)
    if not match:
        return None
    score = float(match.group(1))
    if 1 <= score <= 10:
